// Typeform sends form_response.answers as a list. Match each answer by the field `ref` you set in Typeform.
// Change the refs below to the ones in your form. Missing answers are simply left out.
const response = $input.first().json.body?.form_response ?? {};
const answers = response.answers ?? [];

const pick = (ref) => {
  const a = answers.find((x) => x.field?.ref === ref);
  if (!a) return undefined;
  return a.text ?? a.email ?? a.phone_number ?? a.boolean ?? a.choice?.label ?? a.number;
};

const payload = {
  name: pick('name'),
  email: pick('email'),
  phone: pick('phone'),
  company: pick('company'),
  job_title: pick('job_title'),
  country: pick('country'),
  message: pick('message'),
  consent: pick('consent'),
  // Typeform's token is unique per response, so a redelivered webhook cannot create a second lead.
  external_id: response.token ?? `typeform-${$execution.id}`,
};
for (const k of Object.keys(payload)) if (payload[k] === undefined || payload[k] === '') delete payload[k];

const body = JSON.stringify(payload);
const t = Math.floor(Date.now() / 1000);
return [{ json: { body, t, toSign: `${t}.${body}` } }];
